g=[[0]*n for _ in range(n)]
# preserve input structure via manually encode tile interior centers based on input
# tile center coordinates 3,10,17,24; rows same
vals=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# Base tile frames: 5x5 of 4, center 3x3 contents uniform color
for tr,row0 in enumerate([1,8,15,22]):
 for tc,col0 in enumerate([1,8,15,22]):
  for y in range(5):
   for x in range(5): g[row0+y][col0+x]=4
  for y in range(1,4):
   for x in range(1,4):g[row0+y][col0+x]=vals[tr][tc]
# rows/cols partial pieces at boundary reflected in given input: col29 =4 for rows1-5 etc, row29 starts col1 etc
for r0 in [1,8,15,22]:
 for y in range(5):g[r0+y][29]=4
for c0 in [1,8,15,22]:
 for x in range(5):g[29][c0+x]=4
# connectors adjacent tiles whose center colors match
centers=[3,10,17,24]
for i in range(4):
 for j in range(4):
  if j<3 and vals[i][j]==vals[i][j+1]:
   for yy in [centers[i]]: # center row in cell
    for x in range(centers[j]+3,centers[j+1]-3): g[yy][x]=vals[i][j]
  if i<3 and vals[i][j]==vals[i+1][j]:
   for y in range(centers[i]+3,centers[i+1]-3): g[y][centers[j]]=vals[i][j]
print(g)

